solution.code:
function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function promisify(fn) {
  return (...args) => new Promise((resolve, reject) => {
    fn(...args, (err, result) => {
      if (err) reject(err);
      else resolve(result);
    });
  });
}

const readish = (ok, cb) => setTimeout(() => ok ? cb(null, 'data') : cb(new Error('fail')), 50);
promisify(readish)(true).then((d) => console.log('got', d));

